.grid-lines {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  right: 0;
  z-index: -1;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: space-between;
  --grid-line-color: var(--e-global-color-divider);
  width: 100%;
  max-width: 1300px;
  margin: 0 auto;
}

.grid-line-5,
.grid-line-4,
.grid-line-3,
.grid-line-2,
.grid-line-1 {
  position: relative;
  height: 100%;
}

.grid-line-5:before,
.grid-line-4:before,
.grid-line-3:before,
.grid-line-2:before,
.grid-line-1:before {
  content: "";
  position: absolute;
  top: 0;
  height: 100%;
  right: -1px;
  background: var(--grid-line-color);
  width: 1px;
}

.grid-line-5:after,
.grid-line-4:after,
.grid-line-3:after,
.grid-line-2:after,
.grid-line-1:after {
  content: "";
  position: absolute;
  top: -80px;
  right: -1px;
  background: linear-gradient(
    254deg,
    transparent 0%,
    var(--e-global-color-accent) 50%,
    var(--e-global-color-accentsecondary) 100%
  );
  border-radius: 0;
  opacity: 50%;
  width: 1px;
  height: 60px;
}

.grid-lines .grid-line-1:after {
  animation: gridline 8s linear infinite;
}

.grid-lines .grid-line-2:after {
  animation: gridline 9s linear infinite;
  animation-delay: 3s;
}

.grid-lines .grid-line-3:after {
  animation: gridline 7s linear infinite;
  animation-delay: 6s;
}

.grid-lines .grid-line-4:after {
  animation: gridline 10s linear infinite;
  animation-delay: 4s;
}

.grid-lines .grid-line-5:after {
  animation: gridline 8s linear infinite;
  animation-delay: 8s;
}

@keyframes gridline {
  0% {
    top: -50px;
  }

  to {
    top: 100%;
  }
}

