  text-decoration: none;
  justify-content: center;
  align-items: center;
  background: var(--e-global-color-secondary);
  color: var(--e-global-color-primary);
  border-radius: 10px;
  width: 40px;
  height: 40px;
  margin: 0 5px;
  font-weight: 600;
  line-height: 1em;
