  border-bottom: 0;
  padding-bottom: 0;
}

.post-single-meta ul {
  padding: 0;
  margin: 0;
  list-style: none;
}

.post-single-meta ul li {
  display: inline-block;
  margin-right: 20px;
}

.post-single-meta ul li:last-child {
  margin-right: 0;
}

.post-single-meta ul li i {
  font-size: 16px;
