}

.post-entry h1 {
  font-size: 40px !important;
}

.post-entry h2 {
  font-size: 36px !important;
}

.post-entry h3 {
  font-size: 26px;
}

.post-entry h4 {
  font-size: 22px;
}

.post-entry h5 {
  font-size: 18px;
}

.post-entry h6 {
  font-size: 16px;
}

.post-entry ul {
