  clip-path: inset(50%);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  width: 1px;
  word-wrap: normal;
}

.mejs-container {
  background: #000;
  font-family: Helvetica, Arial, serif;
  position: relative;
  text-align: left;
  text-indent: 0;
  vertical-align: top;
}

.mejs-container,
.mejs-container * {
  box-sizing: border-box;
}

.mejs-container video::-webkit-media-controls,
.mejs-container video::-webkit-media-controls-panel,
.mejs-container video::-webkit-media-controls-panel-container,
.mejs-container video::-webkit-media-controls-start-playback-button {
  -webkit-appearance: none;
  display: none !important;
}

.mejs-fill-container,
.mejs-fill-container .mejs-container {
  height: 100%;
  width: 100%;
}

.mejs-fill-container {
  background: transparent;
  margin: 0 auto;
  overflow: hidden;
  position: relative;
}

.mejs-container:focus {
  outline: none;
}

.mejs-iframe-overlay {
  height: 100%;
  position: absolute;
  width: 100%;
}

.mejs-embed,
.mejs-embed body {
  background: #000;
  height: 100%;
  margin: 0;
  overflow: hidden;
  padding: 0;
  width: 100%;
}

.mejs-fullscreen {
  overflow: hidden !important;
}

.mejs-container-fullscreen {
  bottom: 0;
  left: 0;
  overflow: hidden;
  position: fixed;
  right: 0;
  top: 0;
  z-index: 1000;
}

.mejs-container-fullscreen .mejs-mediaelement,
.mejs-container-fullscreen video {
  height: 100% !important;
  width: 100% !important;
}

.mejs-background,
.mejs-mediaelement {
  left: 0;
  position: absolute;
  top: 0;
}

.mejs-mediaelement {
  height: 100%;
  width: 100%;
  z-index: 0;
}

.mejs-poster {
  background-position: 50% 50%;
  background-repeat: no-repeat;
  background-size: cover;
  left: 0;
  position: absolute;
  top: 0;
  z-index: 1;
}

:root .mejs-poster-img {
  display: none;
}

.mejs-poster-img {
  border: 0;
  padding: 0;
}

.mejs-overlay {
  -webkit-box-align: center;
  -webkit-align-items: center;
  -ms-flex-align: center;
  align-items: center;
  display: -webkit-box;
  display: -webkit-flex;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: center;
  -webkit-justify-content: center;
  -ms-flex-pack: center;
  justify-content: center;
  left: 0;
  position: absolute;
  top: 0;
}

.mejs-layer {
  z-index: 1;
}

.mejs-overlay-play {
  cursor: pointer;
}

.mejs-overlay-button {
  /* background: url(mejs-controls.svg) no-repeat; */
  background-position: 0 -39px;
  height: 80px;
  width: 80px;
}

.mejs-overlay:hover > .mejs-overlay-button {
  background-position: -80px -39px;
}

.mejs-overlay-loading {
  height: 80px;
  width: 80px;
}

.mejs-overlay-loading-bg-img {
  -webkit-animation: a 1s linear infinite;
  animation: a 1s linear infinite;
