  display: block;
  height: 80px;
  width: 80px;
  z-index: 1;
}

@-webkit-keyframes a {
  to {
    -webkit-transform: rotate(1turn);
    transform: rotate(1turn);
  }
}

@keyframes a {
  to {
    -webkit-transform: rotate(1turn);
    transform: rotate(1turn);
  }
}

.mejs-controls {
  bottom: 0;
  display: -webkit-box;
  display: -webkit-flex;
