.mejs-time-buffering {
  -webkit-animation: b 2s linear infinite;
  animation: b 2s linear infinite;
  background: -webkit-linear-gradient(
    135deg,
    hsla(0, 0%, 100%, 0.4) 25%,
    transparent 0,
    transparent 50%,
    hsla(0, 0%, 100%, 0.4) 0,
    hsla(0, 0%, 100%, 0.4) 75%,
    transparent 0,
    transparent
  );
  background: linear-gradient(
    -45deg,
    hsla(0, 0%, 100%, 0.4) 25%,
    transparent 0,
    transparent 50%,
    hsla(0, 0%, 100%, 0.4) 0,
    hsla(0, 0%, 100%, 0.4) 75%,
    transparent 0,
    transparent
  );
  background-size: 15px 15px;
  width: 100%;
}

@-webkit-keyframes b {
  0% {
    background-position: 0 0;
  }

  to {
    background-position: 30px 0;
  }
}

@keyframes b {
  0% {
    background-position: 0 0;
  }

  to {
    background-position: 30px 0;
  }
}

